-- =========================================================
-- INSANITY SOCIETY — Catálogo agosto 2026
-- ⚠ CORRER SOLO UNA VEZ: si lo vuelves a correr, los productos del catálogo
--   vuelven a quedar como en el PDF (se pierden los cambios hechos en el panel).
-- Supabase > SQL Editor > New query > pegar TODO > Run.
--
-- Qué hace:
--  1. Oculta los productos que ya no están en el catálogo (no los borra:
--     puedes volver a mostrarlos desde el panel marcando "Visible").
--  2. Crea los productos nuevos y actualiza precios, materiales, tallas,
--     colores y fotos de los que siguen. OJO: si cambiaste alguno de estos
--     productos desde el panel, este archivo los deja como en el catálogo.
--  3. Actualiza la lista de colecciones (oculta las descontinuadas y agrega
--     las nuevas). Conserva el texto de introducción de Colecciones.
-- =========================================================

-- 1) Ocultar descontinuados
update public.productos set activo = false
where id in ('kyoki-oversize', 'shoka-oversize', 'shugo-oversize', 'blood-and-steel-202', 'raijin-oversize', 'raw-society-oversize', 'break-your-limits', 'still-your-best', 'rift-pantaloneta', 'sixfold-nin', 'sixfold-ha', 'sixfold-retsu', 'sixfold-mamoru', 'sixfold-yami', 'sixfold-tamashii');

-- 2) Productos del catálogo agosto 2026
on conflict (id) do update set
  nombre = excluded.nombre, coleccion = excluded.coleccion, categoria = excluded.categoria,
  material = excluded.material, tallas = excluded.tallas, colores = excluded.colores,
  precio = excluded.precio, variantes = excluded.variantes, imagenes = excluded.imagenes,
  orden = excluded.orden, activo = true;

-- 3) Colecciones
values ('colecciones', $json${"intro":"No son simples diseños. Cada colección cuenta una historia y rinde tributo a valores inquebrantables. Desde espíritus de tormenta hasta pilares que forjan la mente: esta es la esencia detrás de cada pieza.","items":[{"nombre":"THE TRUTH BEHIND THE MASK","jp":"","descripcion":"La verdad detrás de la máscara. Cuatro capítulos y un epílogo sobre la batalla interior: el caos, la disciplina, la verdad y el despertar.","destacada":true,"leyenda_titulo":"La historia","leyenda":"«Todo guerrero libra una batalla que nadie más puede ver.» Cada prenda es un capítulo: Control vs Chaos, Untamed, Revelation, Awakening y The Path of Masks.","enlace":"mascaras.html","enlace_texto":"Leer la historia completa","visible":true},{"nombre":"DARK REBIRTH","jp":"","descripcion":"Estilo que impone presencia. Cortes amplios, diseños crudos. Para entrenar como leyenda y andar como si nada pudiera romperte.","destacada":false,"leyenda_titulo":"","leyenda":"","enlace":"","enlace_texto":"","visible":true},{"nombre":"CLASSIC","jp":"","descripcion":"Las básicas del uniforme de guerra. Sin adornos, sin distracciones: tela dura, corte limpio y presencia pesada. Classic no es moda: es disciplina puesta en tela.","destacada":false,"leyenda_titulo":"","leyenda":"","enlace":"","enlace_texto":"","visible":true},{"nombre":"INSANE","jp":"","descripcion":"No es una colección. Es una declaración. Tipografía brutal, escala exagerada y presencia que ocupa espacio. No busca gustar: busca imponer.","destacada":false,"leyenda_titulo":"","leyenda":"","enlace":"","enlace_texto":"","visible":true},{"nombre":"BAKI-INSPIRED","jp":"","descripcion":"Homenaje al universo de Baki: piezas inspiradas en Baki, Jack y Yujiro. Fuerza, combate y carácter.","destacada":false,"leyenda_titulo":"","leyenda":"","enlace":"","enlace_texto":"","visible":true},{"nombre":"REMEMBER","jp":"","descripcion":"Memento mori: recuerda que morirás. No como una amenaza, sino como un llamado a despertar. El ángel en la espalda simboliza la dualidad: fragilidad y fuerza, caída y renacimiento.","destacada":false,"leyenda_titulo":"","leyenda":"","enlace":"","enlace_texto":"","visible":true},{"nombre":"VERSUS","jp":"","descripcion":"Reto directo: «¿Tú contra mí?». Actitud desafiante; la espalda responde sin rodeos.","destacada":false,"leyenda_titulo":"","leyenda":"","enlace":"","enlace_texto":"","visible":true},{"nombre":"IRON","jp":"","descripcion":"Actitud forjada en hierro. Estética sobria centrada en la terapia del acero.","destacada":false,"leyenda_titulo":"","leyenda":"","enlace":"","enlace_texto":"","visible":true},{"nombre":"OMEN SOCIETY","jp":"","descripcion":"«Bajo la mirada del cielo, levántate y hazte más fuerte». Presencia oscura y decidida.","destacada":false,"leyenda_titulo":"","leyenda":"","enlace":"","enlace_texto":"","visible":true},{"nombre":"REDEMPTION","jp":"","descripcion":"El renacer a través del dolor y la disciplina. Cada repetición, cada gota de sudor y cada herida se convierten en el precio de tu redención: la fuerza.","destacada":false,"leyenda_titulo":"","leyenda":"","enlace":"","enlace_texto":"","visible":true},{"nombre":"SUPER OVERSIZE CARGO","jp":"","descripcion":"Silueta amplia, caída pesada y bolsillos cargo funcionales. No es una prenda para seguir tendencias: es una prenda para imponerlas.","destacada":false,"leyenda_titulo":"","leyenda":"","enlace":"","enlace_texto":"","visible":true},{"nombre":"JOGGERS","jp":"","descripcion":"Corte técnico. Actitud de batalla. Ajuste en tobillos para moverse rápido; perfectos para el hierro, la calle o los días de guerra mental.","destacada":false,"leyenda_titulo":"","leyenda":"","enlace":"","enlace_texto":"","visible":true},{"nombre":"INSANITY ORDER","jp":"","descripcion":"Nueva línea de compresión. Prendas que se pegan a la piel como tu propósito: ajuste firme, secado rápido y presencia que no se olvida.","destacada":false,"leyenda_titulo":"","leyenda":"","enlace":"","enlace_texto":"","visible":true},{"nombre":"NO MERCY","jp":"","descripcion":"Nueva línea de compresión. No es solo ropa: es presión controlada y poder desatado. No estás cómodo, estás concentrado.","destacada":false,"leyenda_titulo":"","leyenda":"","enlace":"","enlace_texto":"","visible":true},{"nombre":"REBELION","jp":"","descripcion":"","destacada":false,"leyenda_titulo":"","leyenda":"","enlace":"","enlace_texto":"","visible":true},{"nombre":"BERSERK","jp":"","descripcion":"Furia icónica; una estética inspirada en el impulso berserker.","destacada":false,"leyenda_titulo":"","leyenda":"","enlace":"","enlace_texto":"","visible":true},{"nombre":"CRYPT","jp":"","descripcion":"Camisillas con diseño gótico de líneas afiladas, en varios colores. Para entrenar ligero sin perder presencia.","destacada":false,"leyenda_titulo":"","leyenda":"","enlace":"","enlace_texto":"","visible":true},{"nombre":"DEATH ASCENT","jp":"","descripcion":"Camisillas de diseño oscuro y simétrico, en varios colores. Hechas para el calor del entrenamiento y la calle.","destacada":false,"leyenda_titulo":"","leyenda":"","enlace":"","enlace_texto":"","visible":true},{"nombre":"SENKI","jp":"戦姫","descripcion":"En Japón, Senki es la mujer que lucha en silencio: la que cae, se levanta y sigue. Suave por fuera, indomable por dentro. Pelea porque rendirse nunca fue una opción.","destacada":false,"leyenda_titulo":"","leyenda":"","enlace":"","enlace_texto":"","visible":true},{"nombre":"PRIMERA EDICIÓN","jp":"","descripcion":"Piezas de introducción con carácter: corte y caída pensados para presencia y comodidad.","destacada":false,"leyenda_titulo":"","leyenda":"","enlace":"","enlace_texto":"","visible":true},{"nombre":"SPORT","jp":"","descripcion":"Prendas de enfoque atlético: secado rápido, frescas y ligeras para moverse y rendir.","destacada":false,"leyenda_titulo":"","leyenda":"","enlace":"","enlace_texto":"","visible":true},{"nombre":"RUNNER","jp":"","descripcion":"Pantaloneta clásica con bolsillos y ranuras laterales, en burda o tela semi impermeable. Opcional con licra por debajo.","destacada":false,"leyenda_titulo":"","leyenda":"","enlace":"","enlace_texto":"","visible":true},{"nombre":"SHORT LICRA","jp":"","descripcion":"Minimalismo funcional: ajuste firme, cómodo y pensado para el esfuerzo.","destacada":false,"leyenda_titulo":"","leyenda":"","enlace":"","enlace_texto":"","visible":true},{"nombre":"TOPS","jp":"","descripcion":"Tops en nylon de alta resistencia y elasticidad, con doble tela: cero transparencias, comodidad y estilo.","destacada":false,"leyenda_titulo":"","leyenda":"","enlace":"","enlace_texto":"","visible":true},{"nombre":"KYO-KI","jp":"狂気","descripcion":"Significado: «locura». Energía desbordante y fuerza interior incontrolable que empuja al guerrero a superarse. «La locura no es debilidad, es el combustible de quienes no temen ir más allá».","destacada":false,"leyenda_titulo":"","leyenda":"","enlace":"","enlace_texto":"","visible":false},{"nombre":"SHOKA","jp":"昇華","descripcion":"The Way of Becoming: del dolor al propósito. Como el koi que desafía la cascada: resistencia, ascenso y transformación.","destacada":false,"leyenda_titulo":"","leyenda":"","enlace":"","enlace_texto":"","visible":false},{"nombre":"SHUGO","jp":"守護","descripcion":"El Guardián. La fuerza que te sostiene cuando todo pesa: disciplina, fuego interno y una presencia que no retrocede ante sus sombras.","destacada":false,"leyenda_titulo":"","leyenda":"","enlace":"","enlace_texto":"","visible":false},{"nombre":"BLOOD AND STEEL","jp":"","descripcion":"Declaración de guerra interna. La sangre como precio del crecimiento y el acero como voluntad inquebrantable; transformación y renacimiento.","destacada":false,"leyenda_titulo":"","leyenda":"","enlace":"","enlace_texto":"","visible":false},{"nombre":"RAIJIN","jp":"","descripcion":"El Guerrero Rojo. Disciplina, concentración y fuerza interior; un legado que renace tras cada caída.","destacada":true,"leyenda_titulo":"Leyenda","leyenda":"En un cielo teñido de rojo, Raijin enfrenta sombras ancestrales hasta caer y renacer en luz carmesí. Su espíritu despierta un legado que marca a doce elegidos con el trueno del guerrero rojo. Raijin no muere; vive en todo aquel que combate y jamás se rinde.","enlace":"raijin.html","enlace_texto":"Leer la leyenda completa ⚡","visible":false},{"nombre":"RAW SOCIETY","jp":"","descripcion":"Crudeza de la calle y fuerza del gimnasio: una propuesta directa, sin filtros, para vivir y entrenar intensamente.","destacada":false,"leyenda_titulo":"","leyenda":"","enlace":"","enlace_texto":"","visible":false},{"nombre":"STREET STRENGTH","jp":"","descripcion":"Fuerza nacida en la calle y liberada en el gimnasio: rebeldía, disciplina y poder real.","destacada":false,"leyenda_titulo":"","leyenda":"","enlace":"","enlace_texto":"","visible":false},{"nombre":"SIXFOLD","jp":"","descripcion":"Seis manifestaciones del poder femenino: oscuridad, alma, protección, furia, transformación y paciencia.","destacada":false,"leyenda_titulo":"","leyenda":"","enlace":"","enlace_texto":"","visible":false},{"nombre":"RIFT","jp":"","descripcion":"Ligereza y movilidad: diseño con aberturas laterales para entrenamiento y calle.","destacada":false,"leyenda_titulo":"","leyenda":"","enlace":"","enlace_texto":"","visible":false}]}$json$::jsonb)
on conflict (clave) do update
  set valor = jsonb_set(public.contenido.valor, '{items}', excluded.valor->'items');
